403	    public async Task StartInDevelopmentWithoutConnectionStringFailsFastNamingTheSetting()
404	    {
405	        await using var factory = new RelayApiFactory(connectionString: null, Environments.Development);
406	
407	        var startupFailure = Should.Throw<Exception>(() => factory.CreateClient().Dispose());
408	
409	        MessagesOf(startupFailure).ShouldContain(
410	            message => message.Contains("ConnectionStrings:Relay", StringComparison.Ordinal)
411	                || message.Contains("ConnectionStrings__Relay", StringComparison.Ordinal));
412	    }
