414	    private static List<string> MessagesOf(Exception startupFailure)
415	    {
416	        var messages = new List<string>();
417	        var pending = new Stack<Exception>([startupFailure]);
418	        while (pending.TryPop(out var exception))
419	        {
420	            messages.Add(exception.Message);
421	            if (exception is AggregateException aggregate)
422	            {
423	                aggregate.InnerExceptions.ToList().ForEach(pending.Push);
424	            }
425	            else if (exception.InnerException is not null)
426	            {
427	                pending.Push(exception.InnerException);
428	            }
429	        }
430	
431	        return messages;
432	    }
